class Solution:
    def canAliceWin(self, a: List[str], b: List[str]) -> bool:
        def cg(w, z):
            return w > z and ord(w[0]) - ord(z[0]) in (0, 1)
        ia, ib = 1, 0
        last, aliceTurn = a[0], False
        while True:
            lst, ptr = (a, ia) if aliceTurn else (b, ib)
            while ptr < len(lst) and not cg(lst[ptr], last):
                ptr += 1
            if ptr == len(lst):
                return not aliceTurn  # mover loses
            last = lst[ptr]
            if aliceTurn: ia = ptr + 1
            else: ib = ptr + 1
            aliceTurn = not aliceTurn

