class Solution {
public:
    bool canAliceWin(vector<string>& a, vector<string>& b) {
        auto cg = [](const string& w, const string& z) {
            return w > z && (w[0] == z[0] || w[0] == z[0] + 1);
        };
        int ia = 1, ib = 0;
        string last = a[0];
        bool aliceTurn = false;
        while (true) {
            vector<string>& lst = aliceTurn ? a : b;
            int& ptr = aliceTurn ? ia : ib;
            while (ptr < (int)lst.size() && !cg(lst[ptr], last)) ptr++;
            if (ptr == (int)lst.size()) return !aliceTurn;
            last = lst[ptr];
            ptr++;
            aliceTurn = !aliceTurn;
        }
    }
};

