class Solution {
    public boolean canAliceWin(List<String> a, List<String> b) {
        int ia = 1, ib = 0;
        String last = a.get(0);
        boolean aliceTurn = false;
        while (true) {
            List<String> lst = aliceTurn ? a : b;
            int ptr = aliceTurn ? ia : ib;
            while (ptr < lst.size() && !cg(lst.get(ptr), last)) ptr++;
            if (ptr == lst.size()) return !aliceTurn;
            last = lst.get(ptr);
            if (aliceTurn) ia = ptr + 1; else ib = ptr + 1;
            aliceTurn = !aliceTurn;
        }
    }
    private boolean cg(String w, String z) {
        return w.compareTo(z) > 0 && (w.charAt(0) == z.charAt(0) || w.charAt(0) == z.charAt(0) + 1);
    }
}

