var canAliceWin = function(a, b) {
    const cg = (w, z) => w > z && (w.charCodeAt(0) - z.charCodeAt(0) === 0 ||
                                   w.charCodeAt(0) - z.charCodeAt(0) === 1);
    let ia = 1, ib = 0, last = a[0], aliceTurn = false;
    while (true) {
        const lst = aliceTurn ? a : b;
        let ptr = aliceTurn ? ia : ib;
        while (ptr < lst.length && !cg(lst[ptr], last)) ptr++;
        if (ptr === lst.length) return !aliceTurn;
        last = lst[ptr];
        if (aliceTurn) ia = ptr + 1; else ib = ptr + 1;
        aliceTurn = !aliceTurn;
    }
};
